import { Api } from 'Api';

const DEFAULT_BFF_URL = '/api/martech-oneway-reports-bff/v1';

const getBffUrl = (): string =>
  localStorage.getItem('bffUrl') || DEFAULT_BFF_URL;

export interface PageCacheResponse {
  html: string;
  isStale?: boolean;
  cacheStatus?: 'fresh' | 'stale';
  shouldRevalidate?: boolean;
  ttlRemainingSeconds?: number | null;
  freshWindowSeconds?: number;
  staleWindowSeconds?: number;
}

export class PageCacheService {
  private static instance: PageCacheService;
  private readonly apiPrefix: string;

  private constructor() {
    this.apiPrefix = getBffUrl();
  }

  public static getInstance(): PageCacheService {
    if (!PageCacheService.instance) {
      PageCacheService.instance = new PageCacheService();
    }
    return PageCacheService.instance;
  }

  async get(
    name: string,
    hash: string,
    signal?: AbortSignal,
  ): Promise<PageCacheResponse | null> {
    try {
      const response = await Api.get({
        url: `${this.apiPrefix}/page-cache/${name}/${hash}`,
        config: { signal },
      });

      if (response?.hasError || response?.status === 404) {
        return null;
      }

      return response?.data as PageCacheResponse;
    } catch {
      return null;
    }
  }

  async set(name: string, hash: string, html: string): Promise<boolean> {
    try {
      const response = await Api.post({
        url: `${this.apiPrefix}/page-cache/${name}/${hash}`,
        body: { html },
      });

      if (response?.hasError) {
        return false;
      }

      return response?.data?.cached ?? false;
    } catch {
      return false;
    }
  }
}
